import{_ as t,o as d,c as o,a2 as c}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"宿主服務","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/dev-guide/sdk/services.md","filePath":"zh-HK/dev-guide/sdk/services.md","lastUpdated":1785993908000}'),r={name:"zh-HK/dev-guide/sdk/services.md"};function a(i,e,s,l,n,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="宿主服務" tabindex="-1">宿主服務 <a class="header-anchor" href="#宿主服務" aria-label="Permalink to &quot;宿主服務&quot;">​</a></h1><p><code>PluginSdk.Services</code> 裏的靜態服務，把宿主應用的功能暴露給插件——每一個都是包裝了宿主啓動時接好的委託的薄靜態類，所以不管底層實際運行的是什麼，插件的調用方式都一樣。</p><table tabindex="0"><thead><tr><th>服務</th><th>用途</th></tr></thead><tbody><tr><td><code>FuzzyMatchService</code></td><td><code>IsMatch(pattern, text)</code> —— <code>text</code>(或它的某個別名)是否匹配 fzf 語法的 <code>pattern</code>,用的是和宿主自身搜尋完全一致的匹配邏輯;<code>GetHighlightMask(text, query)</code> —— 對應這一對 (text, query) 的逐字元高亮掩碼,用的是宿主自己那套字面量/模糊/別名多級兜底算法(含中文拼音),這樣插件自己結果的高亮就能和其他結果保持一致,而不是只能處理簡單的字面量子串匹配。</td></tr><tr><td><code>TranslationService</code></td><td><code>Get(key)</code> / <code>Format(key, args)</code> 在運行時按當前語言查詢;<code>LoadEmbeddedTranslations(assembly, cultureKey, typeName)</code> 加載插件自己內嵌的 JSON 語言包;<code>GetSupportedCultures(assembly)</code>;<code>GetCurrentCulture()</code> —— 應用當前選定的介面語言(比如 <code>&quot;zh-CN&quot;</code>),這是一個獨立於操作系統語言的使用者設定。只有你確實需要拿到原始語言代碼本身時才用它(比如塞進 HTTP 的 <code>Accept-Language</code> 請求頭,或者決定翻譯 API 的目標語言)——<code>CultureInfo.CurrentUICulture</code> 反映的是操作系統的語言,不是這個設定,一旦使用者的 Windows 語言和應用內語言不一致,兩者就會悄悄對不上。</td></tr><tr><td><code>IconService</code></td><td><code>GetIcon(path, isDir)</code> 和 <code>GetThumbnail(path, size)</code> —— 帶快取的 Shell 圖示/縮略圖提取，插件不需要自己調 Windows 圖示 API。</td></tr><tr><td><code>FavoritesService</code></td><td><code>GetFavorites()</code> —— 只讀訪問使用者的<a href="./../../user-guide/settings/favorites.html">收藏夾</a>列表(<code>FavoriteItem</code>:Name、Path)。</td></tr><tr><td><code>HistoryService</code></td><td><code>GetHistoryEntries()</code> —— 每一條已記錄的<a href="./../../user-guide/settings/history.html">歷史記錄</a>條目,按最近打開優先排序,類型是 <code>HistoryEntry { Keyword, Path, Kind, Time }</code>(<code>Kind</code> 是 <code>HistoryEntryKind</code>:<code>File</code> / <code>Folder</code> / <code>Application</code>;<code>Keyword</code> 是打開時輸入框裏的搜尋文字,沒打字就直接打開的話(比如從快速面板的標籤裏點開)就是空字串;<code>Time</code> 是 Unix 秒)。同一個路徑最多只會出現一次,歸屬於最近一次帶它進來的那個關鍵字。</td></tr><tr><td><code>FileMetadataService</code></td><td><code>GetMetadataAsync(paths)</code> —— 批量查詢 Size/Created/Modified/Accessed(<a href="./abstractions.html#filemetadata"><code>FileMetadata</code></a>)，用於查詢<strong>不屬於</strong>你當前結果集的路徑——每個 <code>ISearchResult</code> 本身就通過自己的 <code>Metadata</code> 屬性免費攜帶這些資料(參見<a href="./abstractions.html#isearchresult">共享抽象契約</a>)，所以只有拿到的路徑不是來自結果對象(比如來自你自己的配置)時才需要用這個服務。</td></tr><tr><td><code>DirectoryIndexerService</code></td><td><code>RegisterDirectory(pluginId, path, recursive, filterPattern)</code> / <code>UnregisterDirectories(pluginId)</code> / <code>SearchDirectoriesAsync(pluginId, query, token)</code> —— 讓插件註冊自己的目錄進行後臺索引和 USN 監聽，而不用自己重新實現這套機制。<code>WatchDirectories(pluginId, onChanged)</code> 會在<strong>你自己註冊的</strong>目錄發生磁碟變化時回調你，返回一個 <code>IDisposable</code> 用於退訂。它是按註冊方投遞而不是廣播：沒有 id 要比對，也不會誤處理別人的變化——變化落在誰的註冊上，宿主本來就知道。回調在後台執行緒觸發，而且已經做過防抖(一次批量複製在目錄安靜下來後只回調一次，而不是每個檔案一次)；只有宿主能確實歸因到你的目錄的變化才會通知，歸因不了時(比如整棵樹被重新掃描替換)寧可通知你也不會保持沉默。<code>EnumerateDirectoryAsync(path, recursive, filterPattern, limit, token)</code> 從同一份索引(而不是檔案系統)列出某個目錄的內容——宿主已索引的碟完全不產生磁碟 I/O，沒索引的目錄則自動改為實時遍歷，調用方不需要自己判斷屬於哪種情況。它是串流式的；<code>filterPattern</code> 篩的是<strong>檔案</strong>(目錄一律返回，不需要就按 <code>IsDir</code> 過濾)；隱藏和系統條目永遠不返回；遞歸列舉時值得設 <code>limit</code>——<code>EnumerateDirectoryAsync(@&quot;C:\\&quot;, recursive: true)</code> 會老老實實把整個卷的每一條都交給你。</td></tr><tr><td><code>RecentFilesService</code></td><td><code>GetRecentFilesAsync(directories, limit, maxAgeMinutes, token)</code> —— 一組目錄下最新的項目，最近的在前，由宿主的記憶體索引回答而不是去讀磁碟。是把這些目錄當作<strong>一份</strong>合併列表，而不是每個目錄一份。只含檔案：資料夾自己的修改時間在裏面增刪任何東西時都會變，那會把「正在其中工作」的資料夾頂到一份本該顯示「工作了什麼」的列表最前面。<code>limit</code> 傳 0 表示不限條數，<code>maxAgeMinutes</code> 傳 0 表示不限時間，但兩個都不設的話，一個閒置的資料夾會僅僅因為沒有更新的東西就一直端出一個月前的檔案。宿主沒有索引的目錄不會被即時走訪，而是乾脆不貢獻任何項目——這裏要的是快答案，要麼沒有；慢的那條路請用 <code>DirectoryIndexerService.EnumerateDirectoryAsync</code>。</td></tr><tr><td><code>ExplorerPathService</code></td><td><code>GetLastActivePath()</code> —— 檔案總管視窗或檔案對話方塊最後顯示的那個資料夾，從來沒有過則為 <code>null</code>。它由宿主自己的視窗追蹤填入，跟的是<strong>所有</strong>應用程式的檔案對話方塊，而不只是 Lertaro 自己的介面，所以它的含義是「使用者最後真正在看的那個資料夾」——這是插件自己算不出來的。方向和 <a href="./core-search-actions.html"><code>IActivePathCollector</code></a> 相反：那個是插件<strong>告訴</strong>宿主某個第三方檔案管理員正在顯示什麼，這個是向宿主打聽。不保證仍然存在：它記的是使用者去過哪，而那個資料夾可能早已被刪掉或拔掉了。</td></tr><tr><td><code>PluginSettingsService</code></td><td><code>GetSetting&lt;T&gt;(pluginId, key, defaultValue)</code> —— 從宿主的配置存儲裏只讀訪問插件自己持久化的設定。回退分三層:使用者存過就用持久化的值;沒存過就用你 <code>IConfigurable</code> schema 裏該欄位自己聲明的 <code>DefaultValue</code>;兩者都沒有才輪到你傳進來的 <code>defaultValue</code> 兜底——這樣 schema 裏聲明的預設值就是唯一權威來源,調用方不需要在代碼裏再手寫一份重複的預設值。如果你把某個設定快取了起來而不是每次都重新讀取,記得訂閱 <code>SettingChanged(pluginId, key)</code> 事件,在它為你的插件觸發時清空快取——宿主是在設定頁保存之後立刻觸發這個事件的,這是唯一可靠的失效時機(不管是按鍵觸發還是輪詢檢查,都要等到別的什麼東西湊巧觸發了才會看到變化,或者乾脆永遠看不到)。</td></tr><tr><td><code>SearchRefreshService</code></td><td><code>RefreshIfMatches(queryMatches)</code> —— 給資料是異步到達的 <code>IInstantResultProvider</code> 用的(參見 <a href="./core-search-actions.html#iinstantresultprovider"><code>IInstantResultProvider</code></a>):等你的後臺請求完成、結果也快取好之後，調用這個方法並傳入一個基於當前查詢文字的判斷函數，宿主會把所有匹配這個判斷的、正在進行的搜尋重新跑一遍，這樣剛快取好的結果就能直接顯示出來，不需要使用者重新輸入。</td></tr><tr><td><code>Logger</code></td><td><code>Log(message, level = LogLevel.Info)</code> —— 寫入 App 的日誌檔案，和宿主自己的日誌行一樣，顯示在<strong>設定 → 運行狀態 → App</strong> 裏。</td></tr><tr><td><code>PluginPromptService</code></td><td><code>Prompt(title, fields, initialValues?)</code> —— 彈出一個小的模態視窗，向使用者詢問給定<a href="./abstractions.html#iconfigurable"><code>PluginConfigField</code></a>欄位的值(用的正是 <code>IConfigurable</code> 的配置對話方塊那套欄位 schema/渲染邏輯)，按 <code>Key</code> 匹配從 <code>initialValues</code> 預填，沒有就用各欄位自己的 <code>DefaultValue</code>。返回按欄位 <code>Key</code> 索引的填寫結果，使用者取消則返回 <code>null</code>——這些值不會讀取或寫入插件真正持久化的設定，所以可以放心複用某個配置欄位的 schema 單純做一次性輸入(比如&quot;添加前先給它起個名字&quot;)，不會碰到背後真實的那個設定項。</td></tr></tbody></table><p><code>LogLevel</code> 是 <code>Error</code> / <code>Warn</code> / <code>Info</code> / <code>Debug</code>，與<a href="./../../user-guide/settings/service-status.html">運行狀態日誌查看器</a>裏的等級過濾器一致。</p><h2 id="shell-檔案操作" tabindex="-1">Shell 檔案操作 <a class="header-anchor" href="#shell-檔案操作" aria-label="Permalink to &quot;Shell 檔案操作&quot;">​</a></h2><p><code>Lertaro.PluginSdk.Shell.FileOperations</code> —— 對 Windows shell 自己的 <code>IFileOperation</code> 的一層薄封裝。插件搬動檔案時，用戶看到的是和檔案總管一模一樣的進度對話框、「檔案已存在」提示和復原記錄，而不是一次行為略有不同的 <code>System.IO</code> 調用。</p><table tabindex="0"><thead><tr><th>幫助類</th><th>用途</th></tr></thead><tbody><tr><td><code>ShellPasteHelper</code></td><td><code>PasteAsync(sourcePaths, destinationFolder, move, onCompleted?)</code> —— 把任意多個路徑複製(或移動)進同一個資料夾，合併成<strong>一次</strong> shell 操作，所以跨碟的多選也只彈一個對話框，而不是每個檔案一個。發出即返回：native 對話框可能被用戶晾在那裏，阻塞調用方只會把介面凍住。<code>onCompleted</code> 在操作結束時觸發——不管是複製完了還是用戶取消了，因為對一個正顯示目標資料夾的視圖來說，這兩種情況的應對是同一個：回去重新看一眼。</td></tr><tr><td><code>ShellDeleteHelper</code></td><td><code>DeleteAsync(paths, permanent)</code> —— 放進回收筒或永久刪除，同樣合併成一次操作、一次確認。同樣是發出即返回。</td></tr><tr><td><code>VirtualFileExtractor</code></td><td><code>HasVirtualFiles(dataObject)</code> / <code>Extract(dataObject, targetFolder)</code> —— 把拖動攜帶的、磁碟上還不存在的檔案寫出來：從瀏覽器拖出的圖片、從郵件客戶端拖出的附件、從壓縮檔預覽裏拖出的檔案。它們都不是路徑，所以 <code>IDataObject.GetData(DataFormats.FileDrop)</code> 甚麼也拿不到；真正到來的是一份列出檔名的描述符，加上按索引一次給一個的位元組流，這個類做的就是把它拆出來。刻意不按類型過濾：拒絕拖動方願意交出來的東西，意味著要麼信副檔名、要麼嗅探位元組，這兩件事都不該由它來做。<code>ResolveDestination(folder, name)</code> 是它「重名就加 (2) 而不是覆蓋」的那套命名規則，單獨暴露出來給自己寫檔案的調用方用。</td></tr></tbody></table><p>兩個非同步幫助類都跑在 SDK 自己的 STA 工作執行緒上(<code>ShellOperationStaWorker</code>，由宿主啟動)——shell 的 COM 介面要求 STA，共用一條意味著插件不必自己開一個套間。</p>',8)])])}const p=t(r,[["render",a]]);export{g as __pageData,p as default};
